 #include "matriz_calculadora.h"

 resultado_matriz_mc *
 multiplicar_matrices_mc_1_svc(matrices_mc mat,  struct svc_req *rqstp)
 {
	 static resultado_matriz_mc  result;
 
	 int i, j, k;
 
	 // Inicializar resultado
	 result.filas = mat.A.filas;
	 result.columnas = mat.B.columnas;
 
	 for (i = 0; i < result.filas; i++) {
		 for (j = 0; j < result.columnas; j++) {
			 result.valores.valores_val[i * result.columnas + j] = 0;
			 for (k = 0; k < mat.A.columnas; k++) {
				 result.valores.valores_val[i * result.columnas + j] += 
					 mat.A.valores.valores_val[i * mat.A.columnas + k] * 
					 mat.B.valores.valores_val[k * mat.B.columnas + j];
			 }
		 }
	 }
 
	 return &result;
 }
 